<?php
declare(strict_types=1);
require_once __DIR__ . '/../../includes/functions.php';require_once __DIR__ . '/../../auth/guard.php';require_once __DIR__ . '/../../config/database.php';require_once __DIR__ . '/../../includes/module2_helpers.php';requireAdmin();$title='Quản lý loại căn hộ';$keyword=trim((string)($_GET['keyword']??''));$page=max(1,(int)($_GET['page']??1));$perPage=(int)($_GET['perPage']??10);$perPage=in_array($perPage,[10,20,50,100],true)?$perPage:10;$offset=($page-1)*$perPage;$where='';$params=[];if($keyword!==''){$where='WHERE TenLoai LIKE :kwTen OR MoTa LIKE :kwMoTa';$params=[':kwTen'=>"%$keyword%",':kwMoTa'=>"%$keyword%"];} $stmt=$pdo->prepare("SELECT COUNT(*) FROM LoaiCanHo $where");$stmt->execute($params);$total=(int)$stmt->fetchColumn();$totalPages=max(1,(int)ceil($total/$perPage));$stmt=$pdo->prepare("SELECT l.*,(SELECT COUNT(*) FROM CanHo c WHERE c.MaLoai=l.MaLoai) SoCanHo FROM LoaiCanHo l $where ORDER BY l.MaLoai DESC LIMIT :limit OFFSET :offset");foreach($params as $k=>$v)$stmt->bindValue($k,$v,PDO::PARAM_STR);$stmt->bindValue(':limit',$perPage,PDO::PARAM_INT);$stmt->bindValue(':offset',$offset,PDO::PARAM_INT);$stmt->execute();$items=$stmt->fetchAll();require_once __DIR__ . '/../../includes/header.php';
?><div class="page-header"><div><h1>Loại căn hộ</h1><p class="text-muted">Quản lý danh mục loại căn và giá thuê chuẩn.</p></div><a href="create.php" class="btn btn-primary">+ Thêm loại căn</a></div><form method="get" class="filter-card"><div class="form-group grow"><label>Tìm kiếm</label><input name="keyword" value="<?=e($keyword)?>"></div><button class="btn btn-secondary">Tìm</button><a class="btn btn-light" href="index.php">Xóa lọc</a></form><div class="table-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Mã</th><th>Tên loại</th><th>Giá thuê chuẩn</th><th>Mô tả</th><th>Số căn</th><th>Thao tác</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="6" class="empty-state">Không có dữ liệu.</td></tr><?php else:foreach($items as $item):?><tr><td>#<?=$item['MaLoai']?></td><td><strong><?=e($item['TenLoai'])?></strong></td><td><?=formatMoney($item['GiaThueChuan'])?></td><td><?=e($item['MoTa']??'')?></td><td><?=$item['SoCanHo']?></td><td><a class="btn btn-sm btn-secondary" href="edit.php?id=<?=$item['MaLoai']?>">Sửa</a><?php if(!(int)$item['SoCanHo']):?><form method="post" action="delete.php" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(module2_csrf_token())?>"><input type="hidden" name="id" value="<?=$item['MaLoai']?>"><button class="btn btn-sm btn-danger">Xóa</button></form><?php else:?><span class="text-muted">Đang dùng</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div><?=module2_pagination($page,$totalPages,['keyword'=>$keyword])?><?php require_once __DIR__ . '/../../includes/footer.php'; ?>